@app.post("/register")
def register(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=409, detail="User already exists")
    salt = secrets.token_bytes(16)
    password_hash = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 200000)
    users[username] = {"salt": salt.hex(), "password_hash": password_hash.hex()}
    return {"success": True}

@app.post("/login")
def login(username: str, password: str):
    user = users.get(username)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    salt = bytes.fromhex(user["salt"])
    password_hash = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 200000).hex()
    if not hmac.compare_digest(password_hash, user["password_hash"]):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    return {"access_token": _issue_token(username), "token_type": "bearer"}

@app.get("/me")
def get_me(current_user: str = Depends(get_current_user)):
    return {"username": current_user}
